#!/bin/sh
# Build and run led_controller's host-side test against a checkout of nyx-lib's
# public headers (NYX_LIB_INCLUDE, default ../nyx-lib/include/public). CC and
# EXTRA_CFLAGS choose the compiler and add flags (e.g. -fsanitize=address,undefined);
# BUILD_DIR is where it builds (default: a fresh temporary directory).
set -e
here=$(cd "$(dirname "$0")" && pwd)
top=$(cd "$here/../../.." && pwd)
nyxinc=${NYX_LIB_INCLUDE:-$top/../nyx-lib/include/public}
build=${BUILD_DIR:-$(mktemp -d)}
out=$build/test_keypad
# nyx_version.h is generated by nyx-lib's CMake; make one from the template.
mkdir -p "$build/nyxgen/nyx/common"
sed -e 's/@NYX_API_VERSION_MAJOR@/7/' -e 's/@NYX_API_VERSION_MINOR@/0/' \
    "$nyxinc/nyx/common/nyx_version.h.in" > "$build/nyxgen/nyx/common/nyx_version.h"
# shellcheck disable=SC2086
${CC:-cc} -std=gnu99 -g -Wall -Wextra -Wno-unused-function -Wno-unused-parameter -DTEST_HOST \
    ${EXTRA_CFLAGS:-} \
    -I"$top/src/charger/tests/stubs" -I"$build/nyxgen" -I"$nyxinc" -I"$top/include/internal" \
    -I"$top/src/led_controller" \
    $(pkg-config --cflags glib-2.0 libudev) \
    "$here/test_keypad.c" \
    $(pkg-config --libs glib-2.0 libudev) -ldl -o "$out"
${RUNNER:-} "$out" "$@"
